      ]
    },
    {
      "claim": "Strict, centralized safety standards enabled, rather than stifled, industry-wide innovation and public adoption in the aviation and nuclear industries.",
      "targets": [
        "AN-13"
      ]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Objective, empirical safety metrics can be defined and measured for advanced AI systems.",
      "if_wrong": "If safety cannot be quantified, then any regulatory regime risks becoming purely procedural and thus susceptible to the 'moat' critique."
